function hazardCircle(x,y,r=48,warn=1,life=.35){if(hazards.length>=32)return;hazards.push({kind:'circle',x,y,r,warn,life});}
function hazardBeam(x,y,width=34,warn=1,life=.45){if(hazards.length>=32)return;hazards.push({kind:'beam',x,y,width,warn,life});}
function hazardsStep(dt){for(let h of hazards){let before=h.warn;h.warn-=dt;if(h.warn>0)continue;h.life-=before>0?Math.max(0,dt-before):dt;if(h.life<=0)continue;for(let p of livingPlayers()){let hit=hazardHits(h,p,10);if(hit){if(p===player)damagePlayer();else damagePartner();if(state!=='play')return;}}}hazards=hazards.filter(h=>h.warn>0||h.life>0);}
function majorBossUpdate(dt){let e=boss;e.chill=Math.max(0,(e.chill||0)-dt);let motion=dt*(e.chill>0?.65:1);e.age+=motion;e.fire-=dt;let rage=e.hp<=e.max/2;
if(e.type===6){e.x=W*.5+Math.sin(e.age*.65)*W*.12;e.y=H*.25;}
if(e.type===7){e.x=W*.5+Math.sin(e.age*.5)*W*.25;e.y=H*.28;}
if(e.type===8){e.x=W*.5+Math.sin(e.age*.3)*W*.13;e.y=H*.28;}
if(e.type===9){e.form=Math.floor(e.age/4)%4;if(e.teleport){e.teleport.wait-=dt;if(e.teleport.wait<=0){e.x=e.teleport.x;e.y=e.teleport.y;e.teleport=null;}}}
if(e.burn>0){e.burn-=dt;e.hp-=1.5*dt;if(e.hp<=0)e.dead=true;}
if(!e.dead&&e.fire<=0){e.phase++;let a=targetAngle(e),speed=rage?124:98;
if(e.type===6){let count=rage?14:10;for(let i=0;i<count;i++)fireEnemy(e.x,e.y,a+i*Math.PI*2/count+e.phase*.15,speed);if(e.phase%2===0)for(let p of livingPlayers())hazardCircle(p.x,p.y,42,1,.32);e.attack='Pulse barrage';e.fire=rage?1.35:1.9;}
else if(e.type===7){if(e.phase%2){for(let p of livingPlayers())hazardCircle(p.x,p.y,53,1.1,.4);e.attack='Furnace stomp';}else{let x=90+(e.phase%4)*W*.2;hazardBeam(Math.min(W-60,x),0,42,1.15,.5);for(let i=-2;i<=2;i++)fireEnemy(e.x,e.y,a+i*.23,speed);e.attack='Furnace column';}e.fire=rage?1.35:1.85;}
else if(e.type===8){let gap=(e.phase*3)%16;for(let i=0;i<16;i++)if(i!==gap&&i!==(gap+1)%16)fireEnemy(e.x,e.y,i*Math.PI/8+e.phase*.1,rage?88:70);if(e.phase%3===0){hazardBeam(W*.23,0,30,1.25,.55);hazardBeam(W*.77,0,30,1.25,.55);}e.attack='Silent curtain · find the gap';e.fire=rage?1.15:1.7;}
else{if(e.form===0){for(let i=0;i<12;i++)fireEnemy(e.x,e.y,i*Math.PI/6+e.phase*.25,speed);e.attack='Echo: pressure pulse';}else if(e.form===1){for(let p of livingPlayers())hazardCircle(p.x,p.y,48,1,.35);e.attack='Echo: furnace stomp';}else if(e.form===2){for(let i=-3;i<=3;i++)fireEnemy(e.x,e.y,a+i*.15,speed+15);e.attack='Echo: silent volley';}else{let t={x:100+Math.random()*(W-200),y:85+Math.random()*(H-170),wait:1.15};e.teleport=t;hazardCircle(t.x,t.y,46,1.15,.3);e.attack='Reform · avoid the marked landing';}e.fire=rage?1.25:1.75;}
}
if(!e.dead&&Math.hypot(e.x-player.x,e.y-player.y)<e.r+12)damagePlayer();}

// Unlocks are browser-local; only host-authored per-courier run counters are
// merged. Monotonic cursors make repeated/missed snapshots safe.
const courierChallenges=[
 {id:'rook',key:null,goal:0,text:'Starter courier — available from your first launch.'},
 {id:'frost',key:'firstBoss',goal:1,text:'Defeat the floor 1 boss.'},
 {id:'hop',key:'rooms',goal:10,text:'Clear 10 combat rooms across any number of runs.'},
 {id:'ember',key:'heart',goal:1,text:'Defeat Boiler Heart on floor 3.'},
 {id:'bastion',key:'bosses',goal:5,text:'Defeat 5 bosses across any number of runs.'},
 {id:'vex',key:'flawless',goal:1,text:'Defeat a boss without either courier taking damage in that boss room.'},
 {id:'fuse',key:'recipes',goal:12,text:'Collect 12 recipes yourself across any number of runs.'},
 {id:'sage',key:'cafes',goal:3,text:'Visit 3 unused cafe breaks while injured across any number of runs.'}
];
const progressionKeys=['firstBoss','rooms','heart','bosses','flawless','recipes','cafes'];
let progressionRunOwned=false,progressionStorageOK=true,progressionCursor={key:null,values:{}};
function loadProgression(){let fresh={version:1,stats:Object.fromEntries(progressionKeys.map(k=>[k,0])),unlocked:{rook:true}};
 try{let old=JSON.parse(localStorage.getItem('kitchen-crawl-unlocks-v1')||'null');
 if(old?.version===1&&old.stats&&old.unlocked){for(let k of progressionKeys)if(Number.isFinite(old.stats[k]))fresh.stats[k]=Math.max(0,Math.min(10000000,Math.floor(old.stats[k])));for(let c of couriers)if(old.unlocked[c.id]===true)fresh.unlocked[c.id]=true;}
 else{let marks=Object.values(completionMarks);fresh.stats.heart=marks.some(m=>m.heart)?1:0;fresh.stats.bosses=marks.reduce((n,m)=>n+allMilestones.filter(a=>m[a.id]===true).length,0);fresh.stats.firstBoss=fresh.stats.bosses?1:0;}
 }catch(_){progressionStorageOK=false;}return fresh;
}
let progression=loadProgression();
function saveProgression(){try{localStorage.setItem('kitchen-crawl-unlocks-v1',JSON.stringify(progression));progressionStorageOK=true;}catch(_){progressionStorageOK=false;}}
function courierUnlocked(id){return id==='rook'||progression.unlocked[id]===true;}
function unlockFromStats(notify=true){let unlocked=[];for(let c of courierChallenges)if(!courierUnlocked(c.id)&&progression.stats[c.key]>=c.goal){progression.unlocked[c.id]=true;unlocked.push(courier(c.id).name);}if(unlocked.length&&notify){markToast='Courier unlocked: '+unlocked.join(', ')+(progressionStorageOK?'':' · session only');markToastUntil=performance.now()+6500;}return unlocked;}
function challengeEvent(p,key,n=1){if(!p||!progressionKeys.includes(key)||!Number.isFinite(n)||n<=0)return;p.challengeRun||=Object.fromEntries(progressionKeys.map(k=>[k,0]));p.challengeRun[key]=(p.challengeRun[key]||0)+n;}
function syncProgression(){if(net.role!=='guest'&&!progressionRunOwned)return;let p=net.role==='guest'?partner:player;if(!p?.challengeRun)return;let key=String(sessionRun);if(progressionCursor.key!==key)progressionCursor={key,values:{}};let changed=false;for(let k of progressionKeys){let value=p.challengeRun[k];if(!Number.isFinite(value)||value<0)continue;value=Math.floor(value);let old=progressionCursor.values[k]||0,delta=Math.max(0,value-old);if(delta){progression.stats[k]=Math.min(10000000,progression.stats[k]+delta);changed=true;}progressionCursor.values[k]=Math.max(old,value);}if(changed){unlockFromStats();saveProgression();}}
unlockFromStats(false);saveProgression();

let selectedCourier='rook',remoteCourier='rook',selectionPurpose='solo';
try{let saved=localStorage.getItem('kitchen-crawl-character');if(couriers.some(c=>c.id===saved)&&courierUnlocked(saved))selectedCourier=saved}catch(_){}
function courier(id){return couriers.find(c=>c.id===id)||couriers[0]}
function freshKit(){return {maxHP:7,damage:1,rate:1,spread:0,pierce:false,chili:false,bounce:false,moveSpeed:1,build:[],special:{}}}
const hostKit={get special(){return (player.inventory||=freshKit()).special||= {}},get maxHP(){return maxHP},set maxHP(v){maxHP=v},get damage(){return damage},set damage(v){damage=v},get rate(){return rate},set rate(v){rate=v},get spread(){return spread},set spread(v){spread=v},get pierce(){return pierce},set pierce(v){pierce=v},get chili(){return chili},set chili(v){chili=v},get bounce(){return bounce},set bounce(v){bounce=v},get moveSpeed(){return moveSpeed},set moveSpeed(v){moveSpeed=v},get build(){return build},set build(v){build=v}};
function gear(p=player){return p===player?hostKit:(p.inventory||=freshKit())}
function maxLives(p){return Math.max(2,gear(p).maxHP+courier(p.characterId).hp-7)}
function shotDamage(p){let c=courier(p.characterId);return gear(p).damage+c.damage-1+(c.id==='ember'&&p.hp<=3?.35:0)}
function stepSpeed(p){let c=courier(p.characterId);return 200*gear(p).moveSpeed*c.speed*(c.id==='hop'&&p.boostTime>0?2:1)}
function shotRate(p){let c=courier(p.characterId);return gear(p).rate*c.rate*(c.id==='ember'&&p.boostTime>0?2:1)}
function resetCourier(p,id){p.challengeRun=Object.fromEntries(progressionKeys.map(k=>[k,0]));p.inventory=freshKit();p.foilReady=false;p.decoy=null;p.volleys=0;p.hitCharge=0;p.brineCharge=0;p.steamReadyAt=0;p.droneClock=0;p.emergencyUsed=false;p.supportUsedFloor=0;p.characterId=courier(id).id;p.hp=maxLives(p);p.abilityCooldown=0;p.boostTime=0}
function abilityStep(dt){for(let p of [player,...(coopActive&&partner?[partner]:[])]){p.abilityCooldown=Math.max(0,(p.abilityCooldown||0)-dt);p.boostTime=Math.max(0,(p.boostTime||0)-dt);if(p.decoy){p.decoy.life-=dt;if(p.decoy.life<=0)p.decoy=null}droneStep(p,dt)}}
function useAbility(p){if(state!=='play'||!p||p.hp<=0)return false;let c=courier(p.characterId);if(!c.active||p.abilityCooldown>0)return false;if(c.id==='sage'&&(p.supportUsedFloor===floor||!livingPlayers().some(a=>a.hp<maxLives(a))))return false;p.abilityCooldown=c.cooldown;p.boostTime=c.id==='hop'?.4:c.id==='bastion'?1:c.id==='ember'?3:0;if(c.id==='hop'||c.id==='bastion'){let time=c.id==='hop'?.4:1;if(p===player)inv=Math.max(inv,time);else remoteInv=Math.max(remoteInv,time)}if(c.id==='vex')p.decoy={x:p.x,y:p.y,life:3,hp:1};if(c.id==='fuse')blast(p.x,p.y,150,8+floor*.8,{ownerSlot:p===player?1:2});if(c.id==='sage'){p.supportUsedFloor=floor;for(let a of livingPlayers())heal(1,a)}burst(p.x,p.y,c.color);tone(c.id==='hop'?920:370,.12);hud();return true}
function requestAbility(){if(net.role==='guest')net.send({type:'ability-request'});else useAbility(player);abilityHud()}
function abilityHud(){let p=net.role==='guest'&&partner?partner:player,c=courier(p.characterId);$('ability-button').disabled=state!=='play'||!c.active||p.hp<=0||p.abilityCooldown>0||(c.id==='sage'&&(p.supportUsedFloor===floor||!livingPlayers().some(a=>a.hp<maxLives(a))));$('ability-button').textContent=c.active?(c.active+(c.id==='sage'&&p.supportUsedFloor===floor?' · Used this floor':p.abilityCooldown>0?' · '+Math.ceil(p.abilityCooldown)+'s':' · E / Space')):'Passive only';$('courier-status').textContent=c.name+' · '+(c.passive?'Passive: '+c.passive:'Active: '+c.active)+(c.active&&p.boostTime>0?' · ACTIVE':'');}

let preferences={music:true,volume:70,touch:'auto',reducedMotion:!!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches},settingsSaved=true;
try{let saved=JSON.parse(localStorage.getItem('kitchen-crawl-settings')||'null');if(saved){if(typeof saved.music==='boolean')preferences.music=saved.music;if(Number.isFinite(saved.volume))preferences.volume=Math.max(0,Math.min(100,saved.volume));if(['auto','on','off'].includes(saved.touch))preferences.touch=saved.touch;if(typeof saved.reducedMotion==='boolean')preferences.reducedMotion=saved.reducedMotion}}catch(_){settingsSaved=false}
let menuView='home',menuContext='home',menuExitView='session',connecting=false;
let audio=null,master=null,music=preferences.music,nextNote=0,note=0;
function unlock(){try{if(!audio){audio=new(window.AudioContext||window.webkitAudioContext)();master=audio.createGain();master.connect(audio.destination)}audio.resume().catch(()=>{});master.gain.value=music&&state==='play'?.15*preferences.volume/100:0;nextNote=audio.currentTime}catch(e){}}
function tone(f,d=.1,type='triangle',v=.18,t){if(!audio||!music)return;t=t??audio.currentTime;let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(f,t);g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.001,t+d);o.connect(g);g.connect(master);o.start(t);o.stop(t+d+.01)}
function soundtrack(){if(!audio||!music||state!=='play')return;let scale=boss?[220,261.63,329.63,293.66,220,392,329.63,293.66]:[261.63,329.63,392,523.25,440,392,329.63,293.66],beat=boss?.16:.23;if(nextNote<audio.currentTime-.2)nextNote=audio.currentTime;while(nextNote<audio.currentTime+.1){tone(scale[note%8],beat*.8,'triangle',.2,nextNote);if(note%2===0)tone(scale[(note>>2)%8]/4,beat*1.5,'square',.1,nextNote);note++;nextNote+=beat}}
$('music').onclick=()=>{preferences.music=!music;applyPreferences();storePreferences();unlock()};
function clearInput(){pendingInputs=[];remoteCommands=[];keys.clear();touchMove.clear();touchFire.clear();if(net.role==='guest')net.send({type:'input',keys:[],aim:lastAim})}
function button(text,fn,id,disabled=false){let b=document.createElement('button');b.type='button';b.textContent=text;b.onclick=fn;b.disabled=disabled;b.dataset.gleanId=id;return b}
function panel(title,text){clearInput();$('panel').hidden=false;$('panel-title').textContent=title;$('panel-text').textContent=text;$('choices').replaceChildren();$('pause').disabled=true;if(master)master.gain.value=0}
function resume(){hideMenu();state='play';$('panel').hidden=true;$('pause').disabled=false;$('pause').textContent='Pause';unlock();canvas.focus();hud()}
