function spawnBoss(){let r=rooms[current],kind=r.bossKind,champ=r.champion;let hp=Math.round((kind===13?850:kind===14?1150:isMajorBoss(kind)?110+floor*25:85+floor*27)*(champ?1.55:1)*(coopActive?1.55:1));boss={id:100,x:W/2,y:H*.3,r:isMajorBoss(kind)?48:champ?43:38,hp,max:hp,age:0,fire:1.2,burn:0,type:kind,champion:champ,dash:0,dx:0,dy:0,phase:0,form:0,attack:isMajorBoss(kind)?'Read the warning marks.':''};r.bossDamage=0;}
