function specialStatusStep(dt){for(let e of [...enemies,...(boss?[boss]:[])]){if(e.seasoning)for(let m of Object.values(e.seasoning)){m.life=Math.max(0,m.life-dt);if(m.life===0)m.stacks=0;}if(e.bleed>0&&!e.dead){let time=Math.min(dt,e.bleed);e.bleed=Math.max(0,e.bleed-dt);hitEnemy(e,{damage:time*1.5,secondary:true,quiet:true})}if(e.poison>0&&!e.dead){let time=Math.min(dt,e.poison);e.poison=Math.max(0,e.poison-dt);hitEnemy(e,{damage:time,secondary:true,quiet:true})}if(e.charges){for(let charge of e.charges){charge.wait-=dt;if(charge.wait<=0){if(!e.dead)secondaryHit(e,charge.damage,charge);blast(e.x,e.y,60,charge.damage,charge,e)}}e.charges=e.charges.filter(c=>c.wait>0)}}}
