function renderCharacter(){let c=courier(selectedCourier);$('char-name').textContent=c.name;$('char-tag').textContent=c.tag+' / '+c.inspired;$('char-story').textContent=c.story;$('char-portrait').innerHTML=portrait(c);$('char-health').textContent='♥ '.repeat(c.hp)+' · '+c.hp+' lives';
for(let [key,value,reference] of [['damage',c.damage,1.5],['speed',c.speed,1.3],['rate',c.rate,1.25]]){let n=Math.max(1,Math.round(value/reference*5));$('char-'+key).innerHTML='<span class="stat-marks" aria-hidden="true">'+Array.from({length:5},(_,i)=>'<i'+(i<n?' class="filled"':'')+'></i>').join('')+'</span><span>'+value.toFixed(2)+(key==='damage'?' / fry':key==='speed'?'× move':'× fire')+'</span>';}
$('char-passive').hidden=!c.passive;$('char-passive-name').textContent=c.passive||'';$('char-passive-text').textContent=c.passiveText;$('char-active').hidden=!c.active;$('char-active-name').textContent=c.active||'';$('char-active-text').textContent=(c.activeText||'')+(c.active?(c.id==='sage'?' Once per floor · E / Space or ability button.':' '+c.cooldown+'s cooldown · E / Space or ability button.'):'');$('char-mode').textContent=selectionPurpose==='solo'?'SOLO EXPEDITION':selectionPurpose==='host'?'CO-OP / YOU ARE THE HOST':'CO-OP / YOU ARE THE GUEST';$('char-confirm').textContent=selectionPurpose==='solo'?'Start as '+c.name+' →':selectionPurpose==='host'?'Host as '+c.name+' →':'Join as '+c.name+' →';for(let ch of couriers){let b=$('choose-'+ch.id);b.setAttribute('aria-pressed',String(ch.id===c.id));b.dataset.locked=String(!courierUnlocked(ch.id));b.setAttribute('aria-label',ch.name+(courierUnlocked(ch.id)?' — unlocked':' — locked. '+courierChallenges.find(a=>a.id===ch.id).text));b.innerHTML=portrait(ch)+'<span>'+ch.name+(courierUnlocked(ch.id)?'':' · Locked')+'</span>';}$('char-host-choice').textContent=c.name+' selected · '+c.hp+' base lives · '+c.inspired;$('char-join-choice').textContent=$('char-host-choice').textContent;renderMarks();renderChallenge(c.id);}
for(let c of couriers)$('choose-'+c.id).onclick=()=>chooseCourier(c.id);
$('char-prev').onclick=()=>cycleCourier(-1);$('char-next').onclick=()=>cycleCourier(1);$('char-confirm').onclick=()=>{if(!courierUnlocked(selectedCourier))return;if(selectionPurpose==='solo'){newRun()}else showMenu(selectionPurpose,'home')};
let inventoryPage=0,pendingInventory=false;
function renderInventory(){let local=net.role==='guest'&&partner?partner:player,list=gear(local).build,pages=Math.max(1,Math.ceil(list.length/4));inventoryPage=Math.max(0,Math.min(pages-1,inventoryPage));$('inventory-summary').textContent=courier(local.characterId).name+' · '+list.length+' recipes · Damage '+shotDamage(local).toFixed(2)+' · Speed '+Math.round(stepSpeed(local))+' · Lives '+local.hp+'/'+maxLives(local);$('inventory-synergies').textContent='Active synergies: '+(activeSynergies(local).join(' · ')||'Mix recipes to discover combinations.');$('inventory-content').replaceChildren();for(let name of list.slice(inventoryPage*4,inventoryPage*4+4)){let item=[...items,...dealItems].find(i=>i.name===name),entry=document.createElement('div'),heading=document.createElement('strong'),text=document.createElement('span');entry.className='inventory-entry';heading.textContent=name+(item?.rarity?' · '+item.rarity.toUpperCase():'');text.textContent=item?.text||'Recipe upgrade';entry.append(heading,text);$('inventory-content').append(entry)}if(!list.length){let entry=document.createElement('p');entry.textContent='Classic fries. Collect a recipe to start your build.';$('inventory-content').append(entry)}$('inventory-page').textContent=(inventoryPage+1)+' / '+pages;$('inventory-prev').disabled=inventoryPage===0;$('inventory-next').disabled=inventoryPage>=pages-1;}
