function openInventory(){if(!['play','paused'].includes(state))return;inventoryPage=0;pendingInventory=true;if(state==='play')pause();if(state==='paused')openInventoryPanel()}
$('inventory-open').onclick=openInventory;$('inventory-prev').onclick=()=>{inventoryPage--;renderInventory()};$('inventory-next').onclick=()=>{inventoryPage++;renderInventory()};
$('fullscreen-toggle').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen?.();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else throw Error('Unsupported');resize()}catch(_){markToast='Fullscreen unavailable here. Open the game in its own browser tab or use your browser fullscreen command.';markToastUntil=performance.now()+6000;hud()}};

// Boss expansion: finite rectangular lanes and triangular cones use the same
// local geometry for rendering and circle-versus-shape collision.
function bossStyle(type){return ['sprinkle','grill','cheese','cleaver','ice','coffee','pulse','flame','wave','rift','cleaver','pickle','steam','bell','rift','waffle','batter','noodle'][type]||'orb'}
function hazardShape(kind,x,y,angle,length,width,warn=1.1,life=.45,style='cleaver'){
 if(hazards.length>=32)return;hazards.push({kind,x,y,angle,length,width,warn,life,style});
}
function localHazardPoint(h,p){let a=h.angle||0,dx=p.x-h.x,dy=p.y-h.y;return {x:dx*Math.cos(a)+dy*Math.sin(a),y:-dx*Math.sin(a)+dy*Math.cos(a)}}
function segmentDistance(px,py,ax,ay,bx,by){let dx=bx-ax,dy=by-ay,t=Math.max(0,Math.min(1,((px-ax)*dx+(py-ay)*dy)/(dx*dx+dy*dy||1)));return Math.hypot(px-ax-t*dx,py-ay-t*dy)}
function hazardHits(h,p,r=10){
 if(h.kind==='beam')return p.y+r>=20&&p.y-r<=H-20&&Math.abs(p.x-h.x)<h.width/2+r;
 if(h.kind==='circle')return Math.hypot(p.x-h.x,p.y-h.y)<h.r+r;
 let q=localHazardPoint(h,p),l=h.length,w=h.width/2;
 if(h.kind==='lane'){let x=Math.max(0,Math.min(l,q.x)),y=Math.max(-w,Math.min(w,q.y));return Math.hypot(q.x-x,q.y-y)<r;}
 if(h.kind==='cone'){if(q.x>=0&&q.x<=l&&Math.abs(q.y)<=q.x*w/l)return true;return Math.min(segmentDistance(q.x,q.y,0,0,l,-w),segmentDistance(q.x,q.y,l,-w,l,w),segmentDistance(q.x,q.y,l,w,0,0))<r;}
 return false;
}
function bossLane(e,angle,length=230,width=32,style=bossStyle(e.type),warn=1.15){hazardShape('lane',e.x,e.y,angle,length,width,warn,.42,style)}
function bossUpdate(dt){
 let e=boss,phase=e.phase,oldHazards=hazards.length;
 if(e.type>=15)expansionBossUpdate(dt);else coreBossUpdate(dt);
 if(e.dead)return;
 for(let i=oldHazards;i<hazards.length;i++)hazards[i].style||=bossStyle(e.type);
 if(e.type<15&&e.phase!==phase&&e.phase%3===0)enhanceBoss(e);
}
function enhanceBoss(e){
 let a=targetAngle(e),rage=e.hp<=e.max/2,style=bossStyle(e.type);
 const lane=(angle,length=230,width=32)=>bossLane(e,angle,length,width,style);
 const cone=(angle,length=220,width=140)=>hazardShape('cone',e.x,e.y,angle,length,width,1.2,.45,style);
 if(e.type===0){for(let n of [-1,1])lane(a+n*.48,230,24);e.attack='Sugar scissors · slip between the sprinkle lanes';}
 else if(e.type===1){cone(a,240,180);e.attack='Grill press · leave the triangular grill zone';}
 else if(e.type===2){lane(a,300,50);e.attack='Cheese cutter · step out of the slicing lane';}
 else if(e.type===3){for(let n of [-1,0,1])lane(a+n*.65,210,24);e.attack='Shogun cross-cut · three locked blade lanes';}
 else if(e.type===4){for(let i=0;i<5;i++)lane(a+i*Math.PI*2/5,220,22);e.attack='Deep freeze · dodge the ice fractures';}
 else if(e.type===5){cone(a,250,150);e.attack='Scalding pour · leave the coffee cone';}
 else if(e.type===6){for(let i of [-1,1])lane(a+i*.48,330,40);e.attack='Boiler rupture · twin pressure jets';}
 else if(e.type===7){cone(a,340,210);e.attack='Furnace breath · leave the flame cone';}
 else if(e.type===8){lane(a+Math.PI/2,350,50);lane(a-Math.PI/2,350,50);e.attack='Undertow · avoid both tidal arms';}
 else if(e.type===9){for(let i=0;i<4;i++)lane(a+i*Math.PI/2,300,30);e.attack='Unravelling seams · escape the four rifts';}
 else if(e.type===10){lane(a-.3,260,36);lane(a+.3,260,36);e.attack='Twin chop · locked cleaver lanes';}
 else if(e.type===11){for(let i of [-1,0,1])cone(a+i*.75,200,85);e.attack='Brine breath · three pickled cones';}
 else if(e.type===12){lane(a,280,60);e.attack='Valve failure · high-pressure steam jet';}
 else if(e.type===13){for(let i of [-1,1])lane(a+i*.7,400,44);e.attack='Final chime · escape the bell rays';}
 else{for(let i=0;i<3;i++)cone(a+i*Math.PI*2/3,320,150);e.attack='Table service · three hunger wedges';}
 // Enrage shortens attack cycles in the original patterns, not warning time.
 if(rage)e.attack+=' · ENRAGED';
}
function expansionBossUpdate(dt){
 let e=boss;e.chill=Math.max(0,(e.chill||0)-dt);e.age+=dt*(e.chill>0?.65:1);e.fire-=dt;
 e.x=W*.5+Math.sin(e.age*(e.type===16?.8:.45))*W*.18;e.y=H*.26+Math.cos(e.age*.6)*H*.06;
 if(e.burn>0){e.burn-=dt;e.hp-=1.5*dt;if(e.hp<=0)e.dead=true;}
 if(!e.dead&&e.fire<=0){e.phase++;let a=targetAngle(e),rage=e.hp<=e.max/2,style=bossStyle(e.type);
 if(e.type===15){
  let vertical=e.phase%2===1,gap=e.phase%5,span=vertical?W:H;
  for(let i=0;i<5;i++)if(i!==gap){let at=45+(span-90)*(i+.5)/5;hazardShape('lane',vertical?at:20,vertical?20:at,vertical?Math.PI/2:0,vertical?H-40:W-40,24,1.3,.5,style);}
  e.attack=vertical?'Iron press · escape the vertical waffle bars':'Iron press · escape the horizontal waffle bars';
 }else if(e.type===16){
  for(let n of (rage?[-.7,.7]:[0]))hazardShape('cone',e.x,e.y,a+n,250,160,1.25,.6,style);
  if(e.phase%2===0)for(let i=-2;i<=2;i++)fireEnemy(e.x,e.y,a+i*.32,105);
  e.attack='Batter fan · leave the locked golden wedges';
 }else{
  for(let n=0;n<(rage?4:3);n++)bossLane(e,a+n*Math.PI*2/(rage?4:3)+e.phase*.25,280,26,style,1.2);
  if(e.phase%2===0)for(let i=-1;i<=1;i++)fireEnemy(e.x,e.y,a+i*.2,130);
  e.attack='Noodle lash · step between the locked strands';
 }
 if(e.champion)for(let i of [-1,1])fireEnemy(e.x,e.y,a+i*.4,120);
 e.fire=(rage?1.9:2.55)/(e.champion?1.1:1);
 }
 if(!e.dead&&Math.hypot(e.x-player.x,e.y-player.y)<e.r+12)damagePlayer();
}
function hazardOutline(h){
 ctx.beginPath();
 if(h.kind==='circle')ctx.arc(0,0,h.r,0,Math.PI*2);
 else if(h.kind==='beam')ctx.rect(-h.width/2,20-h.y,h.width,H-40);
 else if(h.kind==='lane')ctx.rect(0,-h.width/2,h.length,h.width);
 else{ctx.moveTo(0,0);ctx.lineTo(h.length,-h.width/2);ctx.lineTo(h.length,h.width/2);ctx.closePath();}
}
function drawHazards(c){for(let h of hazards){
 let warning=h.warn>0,style=h.style||'steam',active=!warning;
 ctx.save();ctx.translate(h.x,h.y);if(h.kind==='lane'||h.kind==='cone')ctx.rotate(h.angle);
 ctx.strokeStyle=c(warning?'gold':'danger');ctx.fillStyle=c(warning?'gold':'danger');ctx.lineWidth=warning?2:3;ctx.setLineDash(warning?[7,4]:[]);
 hazardOutline(h);ctx.globalAlpha=warning?.12:.3;ctx.fill();ctx.globalAlpha=1;ctx.stroke();ctx.setLineDash([]);
 // Clip internal animation to the exact damaging silhouette; outlines never move.
 ctx.save();hazardOutline(h);ctx.clip();
 let left=h.kind==='circle'?-h.r:h.kind==='beam'?-h.width/2:0,right=h.kind==='circle'?h.r:h.kind==='beam'?h.width/2:h.length;
 let top=h.kind==='circle'?-h.r:h.kind==='beam'?20-h.y:-h.width/2,bottom=h.kind==='circle'?h.r:h.kind==='beam'?H-20-h.y:h.width/2;
 let t=preferences.reducedMotion?0:clock,amp=active?1:.3;
 ctx.globalAlpha=active?.85:.4;ctx.lineWidth=2;ctx.strokeStyle=c(style==='ice'||style==='wave'||style==='steam'?'accent':style==='rift'||style==='noodle'?'boss-mist':'gold');ctx.fillStyle=ctx.strokeStyle;
 for(let x=left+8;x<right;x+=22){
  ctx.beginPath();
  if(style==='flame'||style==='coffee'||style==='batter'){for(let y=top+12;y<bottom;y+=24){ctx.moveTo(x-6,y+8);ctx.quadraticCurveTo(x+8*amp*Math.sin(t*5+x),y-16,x+6,y+8);ctx.stroke();}}
  else if(style==='ice'||style==='rift'){ctx.moveTo(x,top);ctx.lineTo(x+7,bottom*.15);ctx.lineTo(x-5,bottom*.6);ctx.lineTo(x+8,bottom);ctx.stroke();}
  else if(style==='noodle'||style==='wave'||style==='steam'){ctx.moveTo(x,top);for(let y=top;y<=bottom;y+=8)ctx.lineTo(x+Math.sin(y*.12+t*5)*4*amp,y);ctx.stroke();}
  else if(style==='pulse'||style==='bell'){ctx.moveTo(x,top);ctx.lineTo(x,bottom*.3);ctx.lineTo(x-6,bottom*.43);ctx.lineTo(x+6,bottom*.55);ctx.lineTo(x,bottom*.7);ctx.lineTo(x,bottom);ctx.stroke();}
  else if(style==='waffle'||style==='grill'){ctx.moveTo(x,top);ctx.lineTo(x,bottom);ctx.moveTo(left,top+(x-left)%(bottom-top||1));ctx.lineTo(right,top+(x-left)%(bottom-top||1));ctx.stroke();}
  else if(style==='cleaver'||style==='cheese'){ctx.moveTo(x-6,top+6);ctx.lineTo(x+7,bottom-6);ctx.lineTo(x+11,bottom-10);ctx.stroke();}
  else{for(let y=top+8;y<bottom;y+=19){ctx.save();ctx.translate(x,y);ctx.rotate(.7);ctx.fillRect(-3,-1,6,2);ctx.restore();}}
 }
 ctx.restore();ctx.globalAlpha=1;ctx.fillStyle=c(warning?'gold':'on');ctx.font='bold 10px system-ui';ctx.textAlign='center';
 // Labels stay upright and use camera-relative anchors in large arenas.
 ctx.restore();let lx=h.kind==='lane'||h.kind==='cone'?h.x+Math.cos(h.angle)*Math.min(70,h.length/2):h.x,ly=h.kind==='lane'||h.kind==='cone'?h.y+Math.sin(h.angle)*Math.min(70,h.length/2):h.kind==='beam'?camera.y+42:h.y;
 ctx.save();ctx.fillStyle=c(warning?'gold':'on');ctx.font='bold 10px system-ui';ctx.textAlign='center';ctx.fillText(warning?'! '+h.warn.toFixed(1):'DANGER',lx,ly);ctx.restore();
}}
function drawBossBullet(b,c){
 if(!b.skin||b.skin==='orb'){circle(b.x,b.y,b.r,'danger');return;}
 ctx.save();ctx.translate(b.x,b.y);ctx.rotate(Math.atan2(b.vy,b.vx));ctx.strokeStyle=c('danger');ctx.fillStyle=c('gold');ctx.lineWidth=2;ctx.beginPath();
 if(b.skin==='cleaver'||b.skin==='cheese'){ctx.moveTo(8,0);ctx.lineTo(-6,-5);ctx.lineTo(-3,5);ctx.closePath();ctx.fill();ctx.stroke();}
 else if(b.skin==='ice'||b.skin==='rift'||b.skin==='pulse'){ctx.moveTo(8,0);ctx.lineTo(0,-5);ctx.lineTo(-8,0);ctx.lineTo(0,5);ctx.closePath();ctx.fill();ctx.stroke();}
 else if(b.skin==='noodle'||b.skin==='wave'||b.skin==='steam'){ctx.moveTo(-10,0);ctx.quadraticCurveTo(-3,-8,1,0);ctx.quadraticCurveTo(5,7,10,0);ctx.stroke();}
 else if(b.skin==='pickle'||b.skin==='coffee'||b.skin==='batter'){ctx.ellipse(0,0,8,4,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle=c('ink');ctx.fillRect(-3,-1,2,2);}
 else{ctx.fillRect(-6,-3,12,6);ctx.strokeRect(-6,-3,12,6);}
 ctx.restore();
}
function drawNewBoss(e,c){
 ctx.save();ctx.translate(e.x,e.y);let z=e.r;ctx.lineWidth=3;ctx.strokeStyle=c('ink');ctx.fillStyle=c(e.type===15?'gold':e.type===16?'danger':'boss-mist');
 if(e.type===15){ctx.fillRect(-z,-z,z*2,z*2);ctx.strokeRect(-z,-z,z*2,z*2);for(let n=-2;n<=2;n++){ctx.beginPath();ctx.moveTo(n*z/3,-z);ctx.lineTo(n*z/3,z);ctx.moveTo(-z,n*z/3);ctx.lineTo(z,n*z/3);ctx.stroke();}ctx.fillRect(-z*.5,-z-10,z,10);}
 else if(e.type===16){ctx.beginPath();ctx.moveTo(-z,-z*.5);ctx.quadraticCurveTo(z*.5,-z*1.4,z,z*.1);ctx.quadraticCurveTo(z*.7,z*1.3,-z*.5,z*.7);ctx.closePath();ctx.fill();ctx.stroke();for(let n=0;n<4;n++){ctx.beginPath();ctx.moveTo(-z*.8+n*16,-z*.5+n*5);ctx.lineTo(-z*1.25+n*16,-z*1.1+n*4);ctx.stroke();}}
 else{ctx.fillStyle=c('road');ctx.beginPath();ctx.moveTo(-z,-z*.15);ctx.quadraticCurveTo(-z*.8,z*1.5,z*.7,z*.7);ctx.lineTo(z,-z*.15);ctx.closePath();ctx.fill();ctx.stroke();ctx.strokeStyle=c('gold');for(let i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(i*16,-z*.1);ctx.bezierCurveTo(i*18-22,-z*1.5,i*18+26,-z*1.2,i*18,-z*1.7);ctx.stroke();}ctx.strokeStyle=c('ink');ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(z*.1,-z*.35);ctx.lineTo(z*1.3,-z*1.25);ctx.stroke();}
 ctx.fillStyle=c('ink');for(let x of [-z*.28,z*.28])ctx.fillRect(x-3,-4,6,9);ctx.beginPath();ctx.moveTo(-z*.2,z*.35);ctx.lineTo(z*.2,z*.35);ctx.stroke();
 if(e.hp<=e.max/2){ctx.strokeStyle=c('danger');ctx.lineWidth=3;ctx.strokeRect(-z-5,-z-5,z*2+10,z*2+10);}
 ctx.restore();
}

